{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Diflunisal, a small carboxylic acid-containing drug with a phenol, achieved 89.5% absolute oral bioavailability in a human volunteer, showing that acidic polar molecules can be well absorbed despite unfavorable physicochemical predictions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Meclofenamate, an anthranilic acid with chloro substituents and a secondary amine, has >85% oral bioavailability in humans, directly supporting high absorption for the query's anthranilic acid-like core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Flufenamic acid, another anthranilic acid NSAID, shows good oral bioavailability and rapid absorption in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "2,4-D, a small chlorinated aryloxyacetic acid, showed rapid and complete oral bioavailability in humans, indicating that small acidic molecules with chlorine can be efficiently absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Telmisartan, a carboxylic acid-containing drug with challenging solubility, had absolute bioavailability of 42% at a 40 mg dose in fasting volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Pazopanib, a sulfonamide-containing drug, had absolute bioavailability of 21.4% in cancer patients, just above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small anthranilic acid/sulfonamide (furosemide). Although the physicochemical prior predicts low permeability, multiple high-transfer experimental analogues with carboxylic acid, sulfonamide, and/or anthranilic acid motifs consistently show absolute oral bioavailability at or above 20%, often much higher. The weight of experimental evidence supports F >=20%; no affirmative experimental evidence supports F <20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query under cystic fibrosis conditions.",
    "Furosemide oral bioavailability is known to be variable, and CF-specific absorption changes are not captured by the supplied analogues.",
    "Most analogues were studied in healthy volunteers or general patient populations, not specifically in cystic fibrosis."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

